function formatChineseText(text,that) {
    const {java} =that || this;
    text = text.replace(/&lt;br&gt;|　| {3,}/g,'\n\n');
    return text.split(/\n\s*\n/).map(para => {let content = para.replace(/\n/g, '<br>');return `<p class="chinese-paragraph">${content}</p>`;}).join('');
}

